	async getAdventureStats() {
		console.log("Calculating adventure stats from Strava + Trip Reports...");
		const stravaActivities = await this.loadStravaActivities();
		const tripReports = await this.getAllTripReports();
		const { uniqueTripReports, duplicatesRemoved } = this.deduplicateActivities(stravaActivities, tripReports);
		const allActivities = [...stravaActivities.map(this.convertStravaToStats), ...uniqueTripReports.map(this.convertTripReportToStats)];
		const peaksWithElevation = new Array(75);
		const totalMiles = Math.round(allActivities.reduce((sum, activity) => sum + (activity.distance || 0), 0));
		const totalElevationGain = Math.round(allActivities.reduce((sum, activity) => sum + (activity.elevation || 0), 0));
		const highestElevation = peaksWithElevation.length > 0 ? Math.max(...peaksWithElevation.map((activity) => activity.elevation || 0)) : 0;
		const currentYear = (/* @__PURE__ */ new Date()).getFullYear();
		const completedThisYear = allActivities.filter((activity) => new Date(activity.date).getFullYear() === currentYear).length;
		const sortedActivities = allActivities.sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime());
		const latestAdventure = sortedActivities.length > 0 ? sortedActivities[0].title : void 0;
		return {
			totalPeaks: peaksWithElevation.length,
			totalMiles,
			highestElevation,
			totalElevationGain,
			completedThisYear,
			latestAdventure,
			stravaActivities: stravaActivities.length,
			tripReports: uniqueTripReports.length,
			duplicatesRemoved
		};
	}
